"""PowerContext 1.4.1 client.

Scope 幂等创建、原子记忆的创建/替换（If-Match ETag）、标签读写（ETag）、
handle 读写、artifact-tags/query、revision 历史、memory/remember、
context/bootstrap、context/prepare。

每次调用都会在模块级 CALL_LOG 里留下一条"请求 / 响应摘要"日志，
供验证脚本和"我的记忆"页面展示。

网络层错误（超时、连接失败）统一抛 PowerContextUnavailable，
调用方据此优雅降级（出题判分照常，界面提示"记忆服务暂不可用"）。
"""
from __future__ import annotations

import json
import threading
from collections import deque
from datetime import datetime, timezone
from typing import Optional

import httpx

from .config import get_settings


class PowerContextUnavailable(Exception):
    """PowerContext 网络不可达 / 超时 / 5xx。调用方应降级而不是失败。"""


# 每条记忆的文本上限（PowerContext 1.4.1 实测）。
MEMORY_TEXT_LIMIT = 8000

CALL_LOG: deque[dict] = deque(maxlen=300)
_LOG_LOCK = threading.Lock()


def _log_call(entry: dict) -> None:
    with _LOG_LOCK:
        CALL_LOG.append(entry)


def recent_calls(limit: int = 100) -> list[dict]:
    with _LOG_LOCK:
        return list(CALL_LOG)[-limit:]


def check_powercontext() -> tuple[bool, str]:
    s = get_settings()
    try:
        resp = httpx.get(f"{s.powercontext_url}/health/ready", timeout=5)
        if resp.status_code == 200:
            return True, "ok"
        return False, f"status={resp.status_code}"
    except Exception as e:
        return False, str(e)


def _summarize(obj, limit: int = 400) -> str:
    try:
        text = obj if isinstance(obj, str) else json.dumps(obj, ensure_ascii=False)
    except Exception:
        text = str(obj)
    text = text.replace("\n", " ")
    return text[:limit] + ("…" if len(text) > limit else "")


class PowerContextClient:
    def __init__(self, base_url: Optional[str] = None, timeout: Optional[float] = None):
        s = get_settings()
        self.base_url = (base_url or s.powercontext_url).rstrip("/")
        self.timeout = timeout if timeout is not None else s.powercontext_timeout_seconds

    # ------------------------------------------------------------------ base

    def _request(self, method: str, path: str, *, json_body: Optional[dict] = None,
                 headers: Optional[dict] = None) -> httpx.Response:
        url = f"{self.base_url}{path}"
        entry = {
            "ts": datetime.now(timezone.utc).isoformat(),
            "method": method,
            "path": path,
            "request": _summarize(json_body if json_body is not None else headers or ""),
        }
        try:
            with httpx.Client(timeout=self.timeout) as client:
                resp = client.request(method, url, json=json_body, headers=headers)
        except httpx.HTTPError as e:
            entry.update(status=None, response=f"网络错误: {type(e).__name__}: {e}")
            _log_call(entry)
            raise PowerContextUnavailable(str(e)) from e
        if resp.status_code >= 500:
            entry.update(status=resp.status_code, response=_summarize(resp.text))
            _log_call(entry)
            raise PowerContextUnavailable(f"HTTP {resp.status_code}: {resp.text[:200]}")
        entry.update(status=resp.status_code,
                     response=_summarize(resp.text if resp.text else "(空响应体)"))
        _log_call(entry)
        return resp

    def _ok_json(self, method: str, path: str, *, json_body: Optional[dict] = None,
                 headers: Optional[dict] = None,
                 expected: tuple[int, ...] = (200, 201)) -> dict:
        resp = self._request(method, path, json_body=json_body, headers=headers)
        if resp.status_code not in expected:
            raise RuntimeError(f"PowerContext {method} {path} 返回 {resp.status_code}: {resp.text[:300]}")
        if not resp.text:
            return {}
        return json.loads(resp.text)

    # ----------------------------------------------------------------- scope

    def ensure_scope(self, learner: str, course_id: str) -> str:
        """按 idempotency_key 幂等创建/取回学习者 × 课程的 Scope。"""
        key = f"examradar:learner:{learner}:course:{course_id}"
        data = self._ok_json(
            "POST", "/v1/scopes",
            json_body={
                "title": f"ExamRadar 学习者 {learner}（课程 {course_id}）",
                "summary": f"ExamRadar 复习教练记忆：学习者 {learner}，课程 {course_id}。",
                "idempotency_key": key,
            },
            expected=(200, 201),
        )
        return data["scope_id"]

    # ------------------------------------------------------------- artifacts

    def create_memory(self, scope_id: str, kind: str, text: str) -> tuple[str, int]:
        """创建原子记忆，返回 (artifact_id, revision)。"""
        if len(text.encode("utf-8")) > MEMORY_TEXT_LIMIT:
            raise ValueError("记忆文本超过 8192 字节上限")
        data = self._ok_json(
            "POST", f"/v1/scopes/{scope_id}/artifacts",
            json_body={
                "family": "atomic-memory",
                "content": {
                    "schema": "powercontext.atomic-memory.v1",
                    "kind": kind,
                    "text": text,
                },
            },
            expected=(200, 201),
        )
        artifact = data.get("artifact") or data
        return artifact["artifact_id"], int(artifact.get("revision") or 1)

    def get_memory(self, scope_id: str, artifact_id: str) -> tuple[str, int]:
        """读原子记忆，返回 (text, revision)。"""
        resp = self._request(
            "GET", f"/v1/scopes/{scope_id}/artifacts/atomic-memory/{artifact_id}")
        if resp.status_code == 404:
            raise RuntimeError(f"artifact {artifact_id} 不存在: {resp.text[:200]}")
        if resp.status_code != 200:
            raise RuntimeError(
                f"GET artifact {artifact_id} 返回 {resp.status_code}: {resp.text[:300]}")
        etag = resp.headers.get("ETag", "")
        revision = _parse_etag(etag, "revision")
        data = json.loads(resp.text)
        # 1.4.1 响应结构：artifact.content.text 或顶层 text
        content = data.get("content") or (data.get("artifact") or {}).get("content") or {}
        text = content.get("text") or data.get("text") or ""
        return text, revision

    def replace_memory(self, scope_id: str, artifact_id: str, kind: str,
                       text: str, retries: int = 2) -> int:
        """If-Match ETag 替换记忆内容，返回新 revision。412 时重读 ETag 重试。"""
        if len(text.encode("utf-8")) > MEMORY_TEXT_LIMIT:
            raise ValueError("记忆文本超过 8192 字节上限")
        body = {
            "family": "atomic-memory",
            "content": {
                "schema": "powercontext.atomic-memory.v1",
                "kind": kind,
                "text": text,
            },
        }
        for attempt in range(retries):
            _, revision = self.get_memory(scope_id, artifact_id)
            resp = self._request(
                "PUT", f"/v1/scopes/{scope_id}/artifacts/atomic-memory/{artifact_id}",
                json_body=body,
                headers={"If-Match": f'"revision:{revision}"'},
            )
            if resp.status_code == 200:
                data = json.loads(resp.text) if resp.text else {}
                return int(data.get("revision") or revision + 1)
            if resp.status_code == 412 and attempt < retries - 1:
                continue
            raise RuntimeError(
                f"PUT artifact {artifact_id} 返回 {resp.status_code}: {resp.text[:300]}")
        raise RuntimeError("unreachable")

    def remember(self, scope_id: str, kind: str, text: str) -> Optional[tuple[str, int]]:
        """memory/remember 追加一条新记忆（不去重）。返回 (artifact_id, revision)。"""
        if len(text.encode("utf-8")) > MEMORY_TEXT_LIMIT:
            raise ValueError("记忆文本超过 8192 字节上限")
        data = self._ok_json(
            "POST", "/v1/memory/remember",
            json_body={"scope_id": scope_id, "kind": kind, "text": text},
        )
        records = data.get("records") or []
        for rec in records:
            artifact = rec.get("artifact") or {}
            if artifact.get("artifact_id"):
                return artifact["artifact_id"], int(artifact.get("revision") or 1)
        return None

    def list_memories(self, scope_id: str, kind: str, limit: int = 50) -> list[dict]:
        """按 kind 列出 active 原子记忆（不走带 tags 的缺陷接口）。"""
        data = self._ok_json(
            "POST", "/v1/atomic-memory/list",
            json_body={"scope_id": scope_id, "kind": kind, "limit": limit},
        )
        items = data.get("items") or data.get("memories") or []
        out = []
        for it in items:
            mem = it.get("memory") or it
            artifact = (it.get("artifact") or mem.get("artifact")
                        or mem.get("reference") or {})
            out.append({
                "artifact_id": artifact.get("artifact_id") or mem.get("artifact_id"),
                "revision": artifact.get("revision") or mem.get("revision"),
                "kind": mem.get("kind") or kind,
                "text": mem.get("text") or (mem.get("content") or {}).get("text") or "",
                "raw": it,
            })
        return out

    def get_revisions(self, scope_id: str, artifact_id: str) -> list[dict]:
        """历次 revision 列表（掌握度变化轨迹）。"""
        data = self._ok_json(
            "GET", f"/v1/scopes/{scope_id}/artifacts/atomic-memory/{artifact_id}/revisions",
            expected=(200, 201),
        )
        items = data.get("items") or data.get("revisions") or []
        if isinstance(items, dict):
            items = list(items.values())
        out = []
        for it in items:
            revision = it.get("revision")
            content = it.get("content") or {}
            out.append({
                "revision": revision if revision is not None else it.get("number"),
                "text": content.get("text") or it.get("text") or "",
                "raw": it,
            })
        out = [r for r in out if r["revision"] is not None]
        out.sort(key=lambda r: int(r["revision"]))
        return out

    # ------------------------------------------------------------------- tags

    def get_tags(self, scope_id: str, artifact_id: str) -> list[str]:
        resp = self._request(
            "GET", f"/v1/scopes/{scope_id}/artifacts/atomic-memory/{artifact_id}/tags")
        if resp.status_code != 200:
            raise RuntimeError(f"GET tags 返回 {resp.status_code}: {resp.text[:300]}")
        data = json.loads(resp.text)
        return data.get("tags") or []

    def put_tags(self, scope_id: str, artifact_id: str, tags: list[str]) -> list[str]:
        """If-Match ETag 更新标签，返回新标签列表。"""
        for _ in range(3):
            resp = self._request(
                "GET", f"/v1/scopes/{scope_id}/artifacts/atomic-memory/{artifact_id}/tags")
            if resp.status_code != 200:
                raise RuntimeError(f"GET tags 返回 {resp.status_code}: {resp.text[:300]}")
            etag = resp.headers.get("ETag", "")
            put = self._request(
                "PUT", f"/v1/scopes/{scope_id}/artifacts/atomic-memory/{artifact_id}/tags",
                json_body={"tags": tags},
                headers={"If-Match": etag},
            )
            if put.status_code == 200:
                data = json.loads(put.text) if put.text else {}
                return data.get("tags") or tags
            if put.status_code == 412:
                continue
            raise RuntimeError(f"PUT tags 返回 {put.status_code}: {put.text[:300]}")
        raise RuntimeError("PUT tags: ETag 冲突重试次数耗尽")

    def query_by_tags(self, scope_id: str, tags: list[str],
                      families: Optional[list[str]] = None) -> list[dict]:
        """artifact-tags/query 按标签查找（规避 1.4.1 的 list/search tags 422 缺陷）。"""
        body: dict = {"tags": tags}
        if families:
            body["families"] = families
        data = self._ok_json(
            "POST", f"/v1/scopes/{scope_id}/artifact-tags/query", json_body=body)
        return data.get("items") or []

    # ---------------------------------------------------------------- handles

    def set_handle(self, scope_id: str, key: str, artifact_id: str, revision: int) -> None:
        self._ok_json(
            "PUT", f"/v1/scopes/{scope_id}/artifact-handles/atomic-memory/{key}",
            json_body={"artifact_id": artifact_id, "revision": revision},
            expected=(200, 201, 204),
        )

    def get_handle(self, scope_id: str, key: str) -> Optional[dict]:
        """按 handle 取记忆引用；还没有时返回 None（404）。"""
        resp = self._request(
            "GET", f"/v1/scopes/{scope_id}/artifact-handles/atomic-memory/{key}")
        if resp.status_code == 404:
            return None
        if resp.status_code != 200:
            raise RuntimeError(f"GET handle {key} 返回 {resp.status_code}: {resp.text[:300]}")
        data = json.loads(resp.text)
        ref = data.get("artifact") or data.get("reference") or data
        artifact = ref.get("artifact") or ref
        return {
            "artifact_id": artifact.get("artifact_id"),
            "revision": artifact.get("revision"),
        }

    # ---------------------------------------------------------------- context

    def bootstrap(self, scope_id: str, event_id: str,
                  max_bytes: int = 2000) -> dict:
        """会话开始时取回 bootstrap-context 记忆。"""
        return self._ok_json(
            "POST", "/v1/context/bootstrap",
            json_body={
                "scope_id": scope_id,
                "enabled": True,
                "lifecycle": "startup",
                "integration": "examradar",
                "event_id": event_id,
                "max_bytes": max_bytes,
            },
        )

    def prepare(self, scope_id: str, query: str, max_bytes: int = 2000) -> dict:
        """按问题准备上下文。query 必须短（知识点 id + 名称）以适配全文召回规则。"""
        return self._ok_json(
            "POST", "/v1/context/prepare",
            json_body={
                "scope_id": scope_id,
                "query": query,
                "max_bytes": max_bytes,
            },
        )

    # ------------------------------------------------------------------ misc

    def health(self) -> tuple[bool, str]:
        try:
            resp = self._request("GET", "/health/ready")
            return resp.status_code == 200, f"status={resp.status_code}"
        except PowerContextUnavailable as e:
            return False, str(e)


def _parse_etag(etag: str, prefix: str) -> int:
    """ETag 形如 "revision:3" / "tags:abc"。取 revision 数字。"""
    inner = etag.strip().strip('"')
    if inner.startswith(f"{prefix}:"):
        value = inner[len(prefix) + 1:]
        try:
            return int(value)
        except ValueError:
            pass
    raise RuntimeError(f"无法从 ETag {etag!r} 解析 {prefix}")


# ------------------------------------------------------------- content parse

def parse_prepared_content(content: str) -> list[dict]:
    """解析 context/prepare 的 content：BEGIN/END 之间是 JSON。

    返回 items 列表（记忆原文 + citation）。解析失败返回 []。
    """
    if not content:
        return []
    begin = content.find("BEGIN_POWERCONTEXT_PREPARED_CONTEXT_V1")
    end = content.find("END_POWERCONTEXT_PREPARED_CONTEXT_V1")
    if begin < 0 or end < 0 or end <= begin:
        return []
    start = begin + len("BEGIN_POWERCONTEXT_PREPARED_CONTEXT_V1")
    payload = content[start:end].strip()
    try:
        data = json.loads(payload)
    except Exception:
        return []
    items = data.get("items") or []
    out = []
    for it in items:
        out.append({
            "text": it.get("content") or "",
            "citation": it.get("citation") or {},
        })
    return out


def bootstrap_opening_line(bootstrap_result: dict) -> Optional[str]:
    """从 bootstrap 结果中取第一条可用记忆的第一行（复习计划的开场白）。

    返回 None 表示 bootstrap 为空 / 不可用。
    """
    if not bootstrap_result or bootstrap_result.get("status") != "ready":
        return None
    content = bootstrap_result.get("content") or ""
    if not content:
        return None
    for line in content.splitlines():
        line = line.strip()
        if line and not line.startswith("BEGIN_") and not line.startswith("END_") \
                and "POWERCONTEXT" not in line:
            return line
    return None

"""Leitner 掌握度递推 + 记忆文本格式（mastery / mistake / plan / session）。

写进记忆的只有判分代码确定的事实：对错、学生自己的答案、正确答案、出处。
掌握度卡片和错题记忆的文本里都写上知识点 id 和名称，
保证 PowerContext 全文召回（"t08 隔离级别与 MVCC" 这类查询）能命中。

卡片 / 计划文本格式：第一行给人看，后面几行 `key: value` 机器可解析。
"""
from __future__ import annotations

import hashlib
import unicodedata
from dataclasses import dataclass, field
from datetime import date, datetime, timedelta, timezone
from typing import Optional

from .config import get_settings


def learner_hash(learner: str) -> str:
    """学习者名字的不可逆短哈希（sha256 前 8 位）。使用记录公开材料里只有它。"""
    return hashlib.sha256(learner.encode("utf-8")).hexdigest()[:8]


# --------------------------------------------------------------------- Leitner

def next_box(box: int, correct: bool) -> int:
    """答对 +1（最多 5）；答错或"不会"回到 1 号盒（经典 Leitner）。"""
    if correct:
        return min(5, box + 1)
    return 1


def next_review(box: int, today: Optional[date] = None) -> date:
    intervals = get_settings().leitner_intervals_list
    days = intervals[box - 1]
    today = today or datetime.now(timezone.utc).date()
    return today + timedelta(days=days)


@dataclass
class MasteryState:
    topic_id: str
    topic_name: str
    box: int = 1
    correct: int = 0
    wrong: int = 0
    next_review: Optional[date] = None
    updated: Optional[str] = None
    extra: dict = field(default_factory=dict)

    def apply_answer(self, correct: bool, today: Optional[date] = None) -> "MasteryState":
        today = today or datetime.now(timezone.utc).date()
        new_box = next_box(self.box, correct)
        return MasteryState(
            topic_id=self.topic_id,
            topic_name=self.topic_name,
            box=new_box,
            correct=self.correct + (1 if correct else 0),
            wrong=self.wrong + (0 if correct else 1),
            next_review=next_review(new_box, today),
            updated=datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
        )


def format_mastery_text(state: MasteryState) -> str:
    """第一行给人看；后面几行机器可解析。"""
    nr = state.next_review.isoformat() if state.next_review else ""
    first = (f"掌握度：{state.topic_name}（{state.topic_id}）—— 盒 {state.box}，"
             f"答对 {state.correct} 次 / 答错 {state.wrong} 次，"
             f"下次复习 {nr}")
    lines = [
        first,
        f"topic_id: {state.topic_id}",
        f"topic_name: {state.topic_name}",
        f"box: {state.box}",
        f"correct: {state.correct}",
        f"wrong: {state.wrong}",
        f"next_review: {nr}",
    ]
    if state.updated:
        lines.append(f"updated: {state.updated}")
    return "\n".join(lines)


def parse_mastery_text(text: str) -> Optional[MasteryState]:
    """从卡片文本解析回状态；解析不出 topic_id 时返回 None。"""
    kv: dict[str, str] = {}
    for line in text.splitlines():
        line = line.strip()
        if ":" in line and not line.startswith("掌握度"):
            key, _, value = line.partition(":")
            kv[key.strip()] = value.strip()
    topic_id = kv.get("topic_id")
    if not topic_id:
        return None
    nr = kv.get("next_review")
    return MasteryState(
        topic_id=topic_id,
        topic_name=kv.get("topic_name", ""),
        box=int(kv.get("box", 1)),
        correct=int(kv.get("correct", 0)),
        wrong=int(kv.get("wrong", 0)),
        next_review=date.fromisoformat(nr) if nr else None,
        updated=kv.get("updated"),
    )


# --------------------------------------------------------------------- mistake

def format_mistake_text(topic_id: str, topic_name: str, question: str,
                        learner_answer: str, correct_answer: str, source: str) -> str:
    """错题记忆：只写判分确定的事实（题目、学生答案、正确答案、出处）。"""
    lines = [
        f"【错题】{topic_id} {topic_name}：题目「{question}」",
        f"你的回答「{learner_answer}」，正确答案「{correct_answer}」，出处 {source}",
        f"topic_id: {topic_id}",
        f"topic_name: {topic_name}",
    ]
    return "\n".join(lines)


# ------------------------------------------------------------------ review plan

@dataclass
class ReviewPlanData:
    opening: str
    wrong_recent: list[str] = field(default_factory=list)   # ["t08:2", ...]
    due_today: list[str] = field(default_factory=list)      # ["t03", ...]
    blind_missing: list[str] = field(default_factory=list)  # ["t04", ...]
    updated: Optional[str] = None


def build_review_plan(data: ReviewPlanData) -> str:
    """第一行就是下次开场要说的话。"""
    lines = [data.opening]
    if data.wrong_recent:
        lines.append("wrong_recent: " + ",".join(data.wrong_recent))
    if data.due_today:
        lines.append("due_today: " + ",".join(data.due_today))
    if data.blind_missing:
        lines.append("blind_missing: " + ",".join(data.blind_missing))
    if data.updated:
        lines.append(f"updated: {data.updated}")
    return "\n".join(lines)


def parse_review_plan(text: str) -> Optional[ReviewPlanData]:
    if not text:
        return None
    lines = [l for l in text.splitlines() if l.strip()]
    if not lines:
        return None
    kv: dict[str, str] = {}
    for line in lines[1:]:
        key, _, value = line.strip().partition(":")
        kv[key.strip()] = value.strip()
    return ReviewPlanData(
        opening=lines[0].strip(),
        wrong_recent=[x for x in kv.get("wrong_recent", "").split(",") if x],
        due_today=[x for x in kv.get("due_today", "").split(",") if x],
        blind_missing=[x for x in kv.get("blind_missing", "").split(",") if x],
        updated=kv.get("updated"),
    )


def build_opening_line(wrong_recent: list[tuple[str, str, int]],
                       due_today: list[tuple[str, str]],
                       blind_missing: list[tuple[str, str, float]]) -> str:
    """开场白，例如：
    上次你在『隔离级别与 MVCC』上错了 2 次，先复习它；『B+树与哈希索引』今天到期；
    『函数依赖与范式』往年考 25 分但笔记里没有。
    """
    parts: list[str] = []
    if wrong_recent:
        tid, name, count = wrong_recent[0]
        parts.append(f"上次你在『{name}』上错了 {count} 次，先复习它")
        for tid, name, count in wrong_recent[1:3]:
            parts.append(f"『{name}』错了 {count} 次")
    for tid, name in due_today[:3]:
        parts.append(f"『{name}』今天到期")
    for tid, name, weight in blind_missing[:2]:
        weight_str = f"{weight:g}"
        parts.append(f"『{name}』往年考 {weight_str} 分但笔记里没有")
    if not parts:
        return "上次没有留下复习记录，从头开始按考试权重复习吧"
    return "；".join(parts)


# ---------------------------------------------------------------- session summary

def format_session_summary(duration_minutes: float, questions_asked: int,
                           questions_correct: int, weak_topics: list[tuple[str, str, int]],
                           started_at: Optional[str] = None) -> str:
    rate = (questions_correct / questions_asked * 100) if questions_asked else 0.0
    first = (f"会话小结：时长 {duration_minutes:.0f} 分钟，做题 {questions_asked} 道，"
             f"正确率 {rate:.0f}%")
    if weak_topics:
        names = "、".join(f"{name}（{topic_id}，错 {count} 次）"
                          for topic_id, name, count in weak_topics[:5])
        first += f"，薄弱点：{names}"
    lines = [first,
             f"duration_minutes: {duration_minutes:.1f}",
             f"questions_asked: {questions_asked}",
             f"questions_correct: {questions_correct}"]
    if weak_topics:
        lines.append("weak_topics: " +
                     ",".join(f"{tid}:{count}" for tid, _n, count in weak_topics))
    if started_at:
        lines.append(f"started_at: {started_at}")
    return "\n".join(lines)


# ------------------------------------------------------------------- grading

def normalize_answer(text: str) -> str:
    """判分归一化：忽略空白、全半角、大小写。"""
    if text is None:
        return ""
    text = unicodedata.normalize("NFKC", str(text))
    text = "".join(text.split())
    return text.lower()


def grade_fill(expected: str, answer: str) -> bool:
    return normalize_answer(expected) == normalize_answer(answer)


def grade_choice(expected: str, answer: str) -> bool:
    return normalize_answer(expected) == normalize_answer(answer)

"""OpenAI 兼容 chat completions 客户端（Ollama /v1 等）。

- 未配置（LLM_BASE_URL / LLM_MODEL 为空）时所有功能走无模型路径。
- qwen3.5 是推理模型：system prompt 追加 /no_think 关闭 thinking，
  解析时再剥一次 <think>…</think>，双保险。
- 同一模型每次调用带同样的 num_ctx（Ollama OpenAI 兼容层接受的 options），
  避免每次重载模型。
- 小模型对写在每一段消息里的具体要求比只写在 system 里的规则更听话，
  所以生成 / 判分的约束同时写进 system 和 user 消息。
"""
from __future__ import annotations

import json
import re
from typing import Optional

import httpx

from .config import get_settings


class LLMError(Exception):
    pass


class LLMClient:
    def __init__(self):
        s = get_settings()
        self.base_url = (s.llm_base_url or "").rstrip("/")
        self.api_key = s.llm_api_key
        self.model = s.llm_model
        self.num_ctx = s.llm_num_ctx

    @property
    def configured(self) -> bool:
        return bool(self.base_url and self.model)

    def chat(self, messages: list[dict], *, temperature: float = 0.3,
             json_mode: bool = False, timeout: float = 120.0) -> str:
        """返回 assistant 消息文本（已剥 thinking）。"""
        if not self.configured:
            raise LLMError("LLM 未配置")
        body: dict = {
            "model": self.model,
            "messages": messages,
            "temperature": temperature,
            "stream": False,
        }
        if self.num_ctx:
            body["options"] = {"num_ctx": self.num_ctx}
        if json_mode:
            body["response_format"] = {"type": "json_object"}
        headers = {}
        if self.api_key:
            headers["Authorization"] = f"Bearer {self.api_key}"
        url = f"{self.base_url}/chat/completions"
        try:
            with httpx.Client(timeout=timeout) as client:
                resp = client.post(url, json=body, headers=headers)
        except httpx.HTTPError as e:
            raise LLMError(f"LLM 网络错误: {e}") from e
        if resp.status_code != 200:
            raise LLMError(f"LLM HTTP {resp.status_code}: {resp.text[:300]}")
        data = resp.json()
        try:
            content = data["choices"][0]["message"]["content"] or ""
        except (KeyError, IndexError, TypeError) as e:
            raise LLMError(f"LLM 响应结构异常: {json.dumps(data, ensure_ascii=False)[:300]}") from e
        return strip_thinking(content)

    def chat_json(self, messages: list[dict], *, temperature: float = 0.2,
                  timeout: float = 120.0) -> dict:
        """要求 JSON 输出并做容错解析。失败抛 LLMError。"""
        text = self.chat(messages, temperature=temperature, json_mode=True, timeout=timeout)
        parsed = parse_json_tolerant(text)
        if not isinstance(parsed, dict):
            raise LLMError("LLM 输出不是 JSON 对象")
        return parsed


def strip_thinking(text: str) -> str:
    """剥掉 qwen3.5 的 <think>…</think>（含未闭合的残段）。"""
    text = re.sub(r"<think>.*?</think>", "", text, flags=re.DOTALL)
    text = re.sub(r"<think>.*$", "", text, flags=re.DOTALL)
    text = re.sub(r"</think>", "", text)
    return text.strip()


def parse_json_tolerant(text: str) -> Optional[object]:
    """容错解析：剥 markdown 代码围栏，找第一个平衡的 {...} 或 [...]。"""
    if not text:
        return None
    cleaned = text.strip()
    fence = re.search(r"```(?:json)?\s*(.*?)```", cleaned, flags=re.DOTALL)
    if fence:
        cleaned = fence.group(1).strip()
    try:
        return json.loads(cleaned)
    except Exception:
        pass
    for opener, closer in (("{", "}"), ("[", "]")):
        start = cleaned.find(opener)
        if start < 0:
            continue
        depth = 0
        in_str = False
        escape = False
        for i in range(start, len(cleaned)):
            ch = cleaned[i]
            if escape:
                escape = False
                continue
            if ch == "\\":
                escape = True
                continue
            if ch == '"':
                in_str = not in_str
                continue
            if in_str:
                continue
            if ch == opener:
                depth += 1
            elif ch == closer:
                depth -= 1
                if depth == 0:
                    try:
                        return json.loads(cleaned[start:i + 1])
                    except Exception:
                        break
        # 括号不平衡：截到最后一个 closer 试试
        last = cleaned.rfind(closer)
        if last > start:
            try:
                return json.loads(cleaned[start:last + 1])
            except Exception:
                pass
    return None


def get_llm_client() -> LLMClient:
    return LLMClient()

