function fmtLocalTime(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  return isNaN(d) ? iso : d.toLocaleString();
}

const SRC = new URLSearchParams(window.location.search).get('source') === 'auto' ? 'auto' : null;
const HDRS = Object.assign({'Content-Type': 'application/json'}, SRC ? {'X-ExamRadar-Source': SRC} : {});

function initReview() {
  const saved = localStorage.getItem('examradar_learner');
  if (saved) document.getElementById('learner-name').value = saved;
  const course = localStorage.getItem('examradar_course');
  if (course) document.getElementById('learner-course').value = course;
}

async function startReview() {
  const learner = document.getElementById('learner-name').value.trim();
  const course = document.getElementById('learner-course').value.trim();
  const el = document.getElementById('opening-line');
  if (!learner) { el.innerHTML = '<span style="color:#888">请先输入你的名字</span>'; return; }
  const btn = document.getElementById('review-start-btn');
  btn.disabled = true; btn.textContent = '开始中...';
  try {
    const r = await fetch('/api/sessions/start', {
      method: 'POST', headers: HDRS,
      body: JSON.stringify({learner, course_id: course})
    });
    const d = await r.json();
    if (!r.ok) { el.innerHTML = '<span style="color:red">' + (d.error || '开始失败') + '</span>'; return; }
    localStorage.setItem('examradar_learner', learner);
    localStorage.setItem('examradar_course', course);
    localStorage.setItem('examradar_session', d.session_id);
    el.innerHTML = (d.memory_ok ? '' : '<div style="color:#c88000">记忆服务暂不可用</div>') +
      (d.opening_line
        ? '<div class="status ok">' + escapeHtml(d.opening_line) + '</div>'
        : '<div class="status">这是你的第一次复习，还没有历史记忆。</div>');
    document.getElementById('enter-coach-btn').style.display = '';
  } catch (e) {
    el.innerHTML = '<span style="color:red">网络错误: ' + escapeHtml(e.message) + '</span>';
  }
  btn.disabled = false; btn.textContent = '开始复习';
}

function enterCoach() {
  window.location.href = '/coach.html' + (SRC ? '?source=auto' : '');
}

function escapeHtml(s) { const d = document.createElement('div'); d.textContent = s == null ? '' : s; return d.innerHTML; }

checkHealth();
loadDocs();
initReview();

