import json

spec = json.load(open('/tmp/pc_openapi.json'))
for path, ops in spec['paths'].items():
    if 'artifacts' in path or 'memory' in path:
        for m, op in ops.items():
            if m in ('put', 'post', 'get'):
                print(m.upper(), path)
                rb = op.get('requestBody', {}).get('content', {}).get('application/json', {}).get('schema', {})
                if rb:
                    print('  body:', json.dumps(rb))
                for p in op.get('parameters', []):
                    if p.get('in') == 'header':
                        print('  header:', p['name'])
print('---schemas---')
for name, sch in spec.get('components', {}).get('schemas', {}).items():
    if 'Replace' in name or 'AtomicMemory' in name:
        print(name, json.dumps(sch))

