244	      return;
245	    }
246	    showMemoryNotice(!d.memory_ok);
247	    renderResult(d);
248	  } catch (e) {
249	    document.getElementById('quiz-result').innerHTML = '<div class="status err">网络错误: ' + escapeHtml(e.message) + '</div>';
250	  }
251	  btn.disabled = false; btn.textContent = '提交回答';
252	}
253	
254	function renderSelfCheck(d) {
255	  const el = document.getElementById('quiz-result');
256	  el.innerHTML = '<div class="card" style="margin:0">' +
257	    '<h3>参考答案</h3><p>' + escapeHtml(d.reference_answer) + '</p>' +
258	    '<p>对照参考答案，你觉得自己掌握了吗？</p>' +
259	    (d.self_ratings || ['会', '模糊', '不会']).map(r =>
260	      `<button class="btn" style="margin:6px 6px 0 0" onclick="submitSelfRating('${r}')">${r}</button>`).join('') +
261	    '</div>';
262	}
263	
264	function renderResult(d) {
265	  const el = document.getElementById('quiz-result');
266	  const cls = d.correct ? 'ok' : 'err';
267	  let html = `<div class="status ${cls}">${d.correct ? '✅' : '❌'} ${escapeHtml(d.feedback)}</div>`;
268	  if (d.box_before != null && d.box_after != null) {
269	    html += `<div class="meta">Leitner 盒号：${d.box_before} → ${d.box_after}</div>`;
270	  }
271	  if (d.explanation) html += '<p>解析：' + escapeHtml(d.explanation) + '</p>';
272	  if (d.misconception) html += '<p>误区：' + escapeHtml(d.misconception) + '</p>';
273	  if (d.mastery) html += `<div class="meta">掌握度卡片：${escapeHtml(d.mastery.artifact_id)} rev ${d.mastery.revision}</div>`;
274	  if (d.mistake_memory && d.mistake_memory.artifact_id) {
275	    html += `<div class="meta">错题记忆：${escapeHtml(d.mistake_memory.artifact_id)} rev ${d.mistake_memory.revision}</div>`;
276	  }
277	  if (d.review_plan) html += `<div class="meta">复习计划：${escapeHtml(d.review_plan.artifact_id)} rev ${d.review_plan.revision}</div>`;
278	  el.innerHTML = html;
279	  document.getElementById('answer-btn').style.display = 'none';
280	  document.getElementById('next-btn').style.display = '';
281	}
282	
283	async function endSession() {
284	  if (!session) return;
285	  const d = await endSessionApi();
286	  session.ended = true;
287	  localStorage.removeItem('examradar_session');
288	  document.getElementById('end-btn').style.display = 'none';
289	  document.getElementById('start-btn').style.display = '';
290	  document.getElementById('quiz-card').style.display = 'none';
291	  if (d) {
292	    const el = document.getElementById('opening-line');
293	    el.innerHTML = '<div class="status">会话已结束：时长 ' + Math.round(d.duration_seconds / 60) +
294	      ' 分钟，做题 ' + d.questions_asked + ' 道，答对 ' + d.questions_correct + ' 道。</div>';
295	  }
296	}
297	
298	async function endSessionApi() {
299	  try {
300	    const r = await fetch('/api/sessions/end', {
301	      method: 'POST', headers: HDRS,
302	      body: JSON.stringify({session_id: session.session_id, source: SRC || 'real'})
303	    });
304	    return await r.json();
305	  } catch (e) { return null; }
306	}
307	
308	function firstLines(text, n) {
309	  return (text || '').split('\n').slice(0, n).join(' ');
310	}
311	
312	function escapeHtml(s) { const d = document.createElement('div'); d.textContent = s == null ? '' : s; return d.innerHTML; }
313	init();
314	</script>
315	</body>
316	</html>
