content.content:
1	<!DOCTYPE html>
2	<html lang="zh-CN">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>我的记忆 — 考前雷达</title>
7	<link rel="stylesheet" href="/static/css/style.css">
8	</head>
9	<body>
10	<header>
11	<div class="container">
12	<h1>考前雷达</h1>
13	<nav>
14	<a href="/">首页</a>
15	<a href="/import.html">导入资料</a>
16	<a href="/ask.html">问笔记</a>
17	<a href="/radar.html">覆盖雷达</a>
18	<a href="/usage.html">使用记录</a>
19	<a href="/coach.html">复习教练</a>
20	<a href="/memory.html">我的记忆</a>
21	</nav>
22	</div>
23	</header>
24	<div class="container">
25	<div class="card">
26	<h2>我的记忆</h2>
27	<div class="form-row">
28	<div>
29	<label for="learner-input">你的名字</label>
30	<input type="text" id="learner-input" placeholder="例如：验收同学">
31	</div>
32	<div>
33	<label for="course-id">课程 ID</label>
34	<input type="text" id="course-id" value="db101">
35	</div>
36	</div>
37	<button class="btn" style="margin-top:12px" onclick="loadMemory()">查看记忆</button>
38	<div id="memory-notice" class="status err" style="display:none;margin-top:12px">记忆服务暂不可用</div>
39	<div id="scope-info" style="margin-top:12px"></div>
40	</div>
41	<div id="memory-area"></div>
42	</div>
43	<script>
44	const SRC = new URLSearchParams(window.location.search).get('source') === 'auto' ? 'auto' : null;
45	const HDRS = Object.assign({'Content-Type': 'application/json'}, SRC ? {'X-ExamRadar-Source': SRC} : {});
46	
47	function ls(key, val) {
48	  if (val !== undefined) localStorage.setItem(key, val);
49	  return localStorage.getItem(key);
50	}
51	
52	function init() {
53	  document.getElementById('learner-input').value = ls('examradar_learner') || '';
54	  document.getElementById('course-id').value = ls('examradar_course') || 'db101';
55	}
56	
57	async function loadMemory() {
58	  const learner = document.getElementById('learner-input').value.trim();
59	  const course = document.getElementById('course-id').value.trim();
60	  if (!learner) { alert('请输入你的名字'); return; }
61	  ls('examradar_learner', learner);
62	  ls('examradar_course', course);
63	  const area = document.getElementById('memory-area');
64	  area.innerHTML = '<div class="card"><p>加载中...</p></div>';
65	  try {
66	    const r = await fetch('/api/memory?learner=' + encodeURIComponent(learner) +
67	      '&course_id=' + encodeURIComponent(course));
68	    const d = await r.json();
69	    if (!r.ok) { area.innerHTML = '<div class="card status err">' + escapeHtml(d.error || '加载失败') + '</div>'; return; }
70	    render(d);
71	  } catch (e) {
72	    area.innerHTML = '<div class="card status err">网络错误: ' + escapeHtml(e.message) + '</div>';
73	  }
74	}
75	
76	function render(d) {
77	  document.getElementById('memory-notice').style.display = d.memory_ok ? 'none' : '';
78	  document.getElementById('scope-info').innerHTML =
79	    d.scope_id ? `<div class="meta">PowerContext Scope：<code>${escapeHtml(d.scope_id)}</code></div>` : '';
80	  const area = document.getElementById('memory-area');
81	  let html = '';
82	
83	  html += '<div class="card"><h2>复习计划</h2>';
84	  if (d.review_plan) {
85	    const p = d.review_plan;
86	    html += `<div class="meta">artifact ${escapeHtml(p.artifact_id)} · revision ${p.revision} · 共 ${p.revisions.length} 个 revision</div>`;
87	    html += '<p>' + escapeHtml((p.text || '').split('\n')[0]) + '</p>';
88	    html += '<details><summary>计划全文</summary><pre>' + escapeHtml(p.text) + '</pre></details>';
89	    html += '<details><summary>revision 历史</summary><ol>' +
90	      p.revisions.map(rv => `<li>rev ${rv.revision}：<pre>${escapeHtml(rv.text)}</pre></li>`).join('') + '</ol></details>';
91	  } else html += '<p style="color:#888">还没有复习计划</p>';
92	  html += '</div>';
93	
94	  html += '<div class="card"><h2>掌握度卡片</h2>';
95	  if (d.mastery_cards && d.mastery_cards.length) {
96	    html += '<table><tr><th>知识点</th><th>盒号</th><th>对/错</th><th>下次复习</th><th>artifact</th><th>轨迹</th></tr>' +
97	      d.mastery_cards.map(c =>
98	        `<tr><td>${escapeHtml(c.topic_id)} ${escapeHtml(c.topic_name)}</td>` +
99	        `<td>${c.box}</td><td>${c.correct}/${c.wrong}</td><td>${escapeHtml(c.next_review || '—')}</td>` +
100	        `<td><code>${escapeHtml(c.artifact_id)}</code> rev ${c.revision}</td>` +
101	        `<td><details><summary>${c.revisions.length} 个 revision</summary><ol>` +
102	        c.revisions.map(rv => `<li>rev ${rv.revision}：${escapeHtml(firstLine(rv.text))}</li>`).join('') +
103	        '</ol></details></td></tr>').join('') + '</table>';
104	  } else html += '<p style="color:#888">还没有掌握度卡片</p>';
105	  html += '</div>';
106	
107	  html += '<div class="card"><h2>错题</h2>';
108	  if (d.mistakes && d.mistakes.length) {
109	    html += d.mistakes.map(m =>
110	      `<div class="result-item"><div class="meta"><code>${escapeHtml(m.artifact_id || '—')}</code> rev ${m.revision ?? '—'}</div>` +
111	      '<pre style="white-space:pre-wrap">' + escapeHtml(m.text) + '</pre></div>').join('');
112	  } else html += '<p style="color:#888">还没有错题记录</p>';
113	  html += '</div>';
114	
115	  html += '<div class="card"><h2>会话小结</h2>';
116	  if (d.session_summaries && d.session_summaries.length) {
117	    html += d.session_summaries.map(m =>
118	      `<div class="result-item"><div class="meta"><code>${escapeHtml(m.artifact_id || '—')}</code> rev ${m.revision ?? '—'}</div>` +
119	      '<pre style="white-space:pre-wrap">' + escapeHtml(m.text) + '</pre></div>').join('');
120	  } else html += '<p style="color:#888">还没有会话小结</p>';
121	  html += '</div>';
122	
123	  if (d.bootstrap) {
124	    html += '<div class="card"><h2>bootstrap 校验</h2>' +
125	      `<div class="meta">status: ${escapeHtml(d.bootstrap.status || '—')}${d.bootstrap.reason ? ' · ' + escapeHtml(d.bootstrap.reason) : ''}</div>`;
126	    if (d.bootstrap.items && d.bootstrap.items.length) {
127	      html += '<ul>' + d.bootstrap.items.map(it =>
128	        `<li><code>${escapeHtml(it.artifact_id || '—')}</code> rev ${it.revision ?? '—'}</li>`).join('') + '</ul>';
129	      html += '<details><summary>bootstrap content</summary><pre>' + escapeHtml(d.bootstrap.content || '') + '</pre></details>';
130	    }
131	    html += '</div>';
132	  }
133	
134	  if (d.pc_calls && d.pc_calls.length) {
135	    html += '<div class="card"><h2>PowerContext 请求 / 响应摘要</h2>' +
136	      '<table><tr><th>时间</th><th>请求</th><th>状态</th><th>响应摘要</th></tr>' +
137	      d.pc_calls.slice().reverse().map(c =>
138	        `<tr><td>${escapeHtml((c.ts || '').replace('T',' ').slice(0,19))}</td>` +
139	        `<td><code>${escapeHtml(c.method)} ${escapeHtml(c.path)}</code><br><span style="color:#888">${escapeHtml(String(c.request || '').slice(0,120))}</span></td>` +
140	        `<td>${c.status ?? '—'}</td><td style="color:#888">${escapeHtml(String(c.response || '').slice(0,160))}</td></tr>`).join('') +
141	      '</table></div>';
142	  }
143	  area.innerHTML = html;
144	}
145	
146	function firstLine(t) { return (t || '').split('\n')[0]; }
147	function escapeHtml(s) { const d = document.createElement('div'); d.textContent = s == null ? '' : s; return d.innerHTML; }
148	init();
149	</script>
150	</body>
151	</html>
